			function selectMdiItem(pnItemId, pbIsSave) {
			    var grpFltBtns = app.lookup("grpFltBtns");
			    
			    util.Tab.setSelectedTabItemById(app, "mdi", pnItemId);
			    
			    switch (pnItemId) {
			        case 1:
			            grpFltBtns.visible = true;
			            if (pbIsSave)
			                doList("save");
			                setCrud("READ");
			            break;
			        case 2:
			            grpFltBtns.visible = false;
			            setCrud("READ");
			            break;
			    }
			}
